            else:
                mask &= full & ~((1 << (cells[j] + 1)) - 1)
    return mask

def count(cells, n, rows, cols, links, full):
    best, best_mask, best_count = -1, 0, n + 1
    for i in range(n * n):
        if cells[i] == 0:
            mask = candidates(cells, n, rows, cols, links, full, i)
            c = bin(mask).count("1")
            if c < best_count:
                best, best_mask, best_count = i, mask, c
                if c <= 1:
                    break
    if best == -1:
        return 1
    if best_count == 0:
        return 0
