        if best_mask & bit:
            cells[best] = d
            rows[r] |= bit
            cols[c0] |= bit
            total += count(cells, n, rows, cols, links, full)
            cells[best] = 0
            rows[r] &= ~bit
            cols[c0] &= ~bit
    return total

